@@ -0,0 +1,33 @@
+export function parseEnvMetadata(text) {
+  const lines = text.split('\n');
+  const result = [];
+  
+  for (const line of lines) {
+    // Skip blank lines and comments
+    if (!line || line.trim().startsWith('#')) continue;
+    
+    // Remove optional leading 'export '
+    let processedLine = line;
+    if (processedLine.startsWith('export ')) {
+      processedLine = processedLine.slice(7);
+    }
+    
+    // Check for valid assignment
+    const eqIndex = processedLine.indexOf('=');
+    if (eqIndex === -1) continue; // Skip malformed lines without '='
+    
+    const namePart = processedLine.substring(0, eqIndex).trim();
+    const valuePart = processedLine.substring(eqIndex + 1);
+    
+    // Validate name pattern: [A-Za-z_][A-Za-z0-9_]*
+    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(namePart)) continue; // Skip malformed names
+    
+    // Check presence: raw value after first =, trimmed, length > 0
+    const trimmedValue = valuePart.trim();
+    const present = trimmedValue.length > 0;
+    
+    result.push({ name: namePart, present });
+  }
+  
+  return Object.freeze(result.map(item => Object.freeze(item)));
+}

